static lstr L11179 = {0, 9044, "// std/shape: Value, a dynamic tree for structured data, and the Shape trait.\012//\012// Formats such as std/json read and write Value. Int and Float are separate\012// because a 64-bit integer must survive a round trip, which an f64 cannot hold.\012// Record keeps its fields in insertion order.\012//\012// Shape converts a type to and from Value. The compiler provides it for bool,\012// int, f64, char, string, Array<T>, Map<string, V>, Option<T> and tuples of two\012// to four items, when their contents implement it: a call of Shape.toValue or\012// Shape.fromValue on such a type runs the matching private function\012// below. Value, a struct and an enum implement it with an `implement` block.\012//\012// A decode error reads `<path>: <reason>` with the path from the root\012// (`.users[2].age: expected int, found Text`); at the root it is the reason alone.\012\012import * as Str from \"std/string\"\012import * as Int from \"std/int\"\012import * as Float from \"std/float\"\012import * as Arrays from \"std/array\"\012import * as Maps from \"std/map\"\012\012export enum Value implements Shape {\012  Null\012  Bool(value: bool)\012  Int(value: int)\012  Float(value: f64)\012  Text(value: string)\012  List(items: Array<Value>)\012  Record(fields: Map<string, Value>)\012}\012\012export trait Shape {\012  function toValue(value: Self): Value from value uses alloc\012  function fromValue(value: Value): Result<Self, string> from value uses alloc\012}\012\012implement Shape for Value {\012  function toValue(value: Value): Value from value uses alloc {\012    return value\012  }\012\012  function fromValue(value: Value): Result<Value, string> from value uses alloc {\012    return Ok(value)\012  }\012}\012\012// The name of a Value variant, for error messages.\012function kindName(value: Value): string {\012  return match (value) {\012    Value.Null => \"Null\"\012    Value.Bool(_) => \"Bool\"\012    Value.Int(_) => \"Int\"\012    Value.Float(_) => \"Float\"\012    Value.Text(_) => \"Text\"\012    Value.List(_) => \"List\"\012    Value.Record(_) => \"Record\"\012  }\012}\012\012function mismatch(expected: string, value: Value): string uses alloc {\012  return `expected ${expected}, found ${kindName(value)}`\012}\012\012// prefixPath puts a path segment (`.name` or `[2]`) in front of a child error.\012// A child error that already starts with a path keeps it after the segment.\012function prefixPath(segment: string, message: string): string uses alloc {\012  if (Str.startsWith(message, \".\") || Str.startsWith(message, \"[\")) {\012    return `${segment}${message}`\012  }\012  return `${segment}: ${message}`\012}\012\012function boolToValue(value: bool): Value {\012  return Value.Bool(value)\012}\012\012function boolFromValue(value: Value): Result<bool, string> uses alloc {\012  if (value is Value.Bool(flag)) {\012    return Ok(flag)\012  }\012  return Err(mismatch(\"bool\", value))\012}\012\012function intToValue(value: int): Value {\012  return Value.Int(value)\012}\012\012function intFromValue(value: Value): Result<int, string> uses alloc {\012  if (value is Value.Int(number)) {\012    return Ok(number)\012  }\012  return Err(mismatch(\"int\", value))\012}\012\012function floatToValue(value: f64): Value {\012  return Value.Float(value)\012}\012\012function floatFromValue(value: Value): Result<f64, string> uses alloc {\012  if (value is Value.Float(number)) {\012    return Ok(number)\012  }\012  if (value is Value.Int(whole)) {\012    return Ok(Float.fromInt(whole))\012  }\012  return Err(mismatch(\"f64\", value))\012}\012\012function charToValue(value: char): Value uses alloc {\012  return Value.Text(Str.fromChar(value))\012}\012\012function charFromValue(value: Value): Result<char, string> uses alloc {\012  if (value is Value.Text(text)) {\012    if (Str.charCount(text) == 1) {\012      return Ok(Str.charAt(text, 0))\012    }\012    return Err(\"expected one character, found Text of a different length\")\012  }\012  return Err(mismatch(\"char\", value))\012}\012\012function stringToValue(value: string): Value {\012  return Value.Text(value)\012}\012\012function stringFromValue(value: Value): Result<string, string> uses alloc {\012  if (value is Value.Text(text)) {\012    return Ok(text)\012  }\012  return Err(mismatch(\"string\", value))\012}\012\012function arrayToValue<T: Shape>(value: Array<T>): Value from value uses alloc {\012  let items: Array<Value> = []\012  for (const item of Arrays.values(value)) {\012    Arrays.push(mutable items, Shape.toValue(item))\012  }\012  return Value.List(items)\012}\012\012function arrayFromValue<T: Shape>(value: Value): Result<Array<T>, string> uses alloc {\012  if (value is Value.List(items)) {\012    let out: Array<T> = []\012    for (const #[index, item] of Arrays.entries(items)) {\012      const decoded = Shape.fromValue<T>(item)\012      if (decoded is Err(message)) {\012        return Err(prefixPath(`[${Int.toString(index)}]`, message))\012      }\012      Arrays.push(mutable out, decoded.value)\012    }\012    return Ok(out)\012  }\012  return Err(mismatch(\"List\", value))\012}\012\012function mapToValue<V: Shape>(value: Map<string, V>): Value from value uses alloc {\012  let fields: Map<string, Value> = Map {}\012  for (const entry of Maps.entries(value)) {\012    const #[key, field] = entry\012    fields[key] = Shape.toValue(field)\012  }\012  return Value.Record(fields)\012}\012\012function mapFromValue<V: Shape>(value: Value): Result<Map<string, V>, string> uses alloc {\012  if (value is Value.Record(fields)) {\012    let out: Map<string, V> = Map {}\012    for (const entry of Maps.entries(fields)) {\012      const #[key, field] = entry\012      const decoded = Shape.fromValue<V>(field)\012      if (decoded is Err(message)) {\012        return Err(prefixPath(`.${key}`, message))\012      }\012      out[key] = decoded.value\012    }\012    return Ok(out)\012  }\012  return Err(mismatch(\"Record\", value))\012}\012\012function optionToValue<T: Shape>(value: Option<T>): Value from value uses alloc {\012  if (value is Some(inner)) {\012    return Shape.toValue(inner)\012  }\012  return Value.Null\012}\012\012function optionFromValue<T: Shape>(value: Value): Result<Option<T>, string> from value uses alloc {\012  if (value is Value.Null) {\012    return Ok(None)\012  }\012  const decoded = Shape.fromValue<T>(value)\012  if (decoded is Err(message)) {\012    return Err(message)\012  }\012  return Ok(Some(decoded.value))\012}\012\012// A tuple is a List of exactly count items.\012function tupleItems(value: Value, count: int): Result<Array<Value>, string> from value uses alloc {\012  if (value is Value.List(items)) {\012    if (Arrays.length(items) != count) {\012      const found = Int.toString(Arrays.length(items))\012      return Err(`expected a List of ${Int.toString(count)} items, found ${found}`)\012    }\012    return Ok(items)\012  }\012  return Err(mismatch(\"List\", value))\012}\012\012function tuple2ToValue<A: Shape, B: Shape>(value: #[A, B]): Value from value uses alloc {\012  const #[first, second] = value\012  return Value.List([Shape.toValue(first), Shape.toValue(second)])\012}\012\012function tuple2FromValue<A: Shape, B: Shape>(value: Value): Result<#[\012  A,\012  B,\012], string> from value uses alloc {\012  const items = tupleItems(value, 2)\012  if (items is Err(problem)) {\012    return Err(problem)\012  }\012  const first = Shape.fromValue<A>(items.value[0])\012  if (first is Err(message)) {\012    return Err(prefixPath(\"[0]\", message))\012  }\012  const second = Shape.fromValue<B>(items.value[1])\012  if (second is Err(message)) {\012    return Err(prefixPath(\"[1]\", message))\012  }\012  return Ok(#[first.value, second.value])\012}\012\012function tuple3ToValue<A: Shape, B: Shape, C: Shape>(\012  value: #[A, B, C],\012): Value from value uses alloc {\012  const #[first, second, third] = value\012  return Value.List([Shape.toValue(first), Shape.toValue(second), Shape.toValue(third)])\012}\012\012function tuple3FromValue<A: Shape, B: Shape, C: Shape>(value: Value): Result<#[\012  A,\012  B,\012  C,\012], string> from value uses alloc {\012  const items = tupleItems(value, 3)\012  if (items is Err(problem)) {\012    return Err(problem)\012  }\012  const first = Shape.fromValue<A>(items.value[0])\012  if (first is Err(message)) {\012    return Err(prefixPath(\"[0]\", message))\012  }\012  const second = Shape.fromValue<B>(items.value[1])\012  if (second is Err(message)) {\012    return Err(prefixPath(\"[1]\", message))\012  }\012  const third = Shape.fromValue<C>(items.value[2])\012  if (third is Err(message)) {\012    return Err(prefixPath(\"[2]\", message))\012  }\012  return Ok(#[first.value, second.value, third.value])\012}\012\012function tuple4ToValue<A: Shape, B: Shape, C: Shape, D: Shape>(\012  value: #[A, B, C, D],\012): Value from value uses alloc {\012  const #[first, second, third, fourth] = value\012  return Value.List([\012    Shape.toValue(first),\012    Shape.toValue(second),\012    Shape.toValue(third),\012    Shape.toValue(fourth),\012  ])\012}\012\012function tuple4FromValue<A: Shape, B: Shape, C: Shape, D: Shape>(value: Value): Result<#[\012  A,\012  B,\012  C,\012  D,\012], string> from value uses alloc {\012  const items = tupleItems(value, 4)\012  if (items is Err(problem)) {\012    return Err(problem)\012  }\012  const first = Shape.fromValue<A>(items.value[0])\012  if (first is Err(message)) {\012    return Err(prefixPath(\"[0]\", message))\012  }\012  const second = Shape.fromValue<B>(items.value[1])\012  if (second is Err(message)) {\012    return Err(prefixPath(\"[1]\", message))\012  }\012  const third = Shape.fromValue<C>(items.value[2])\012  if (third is Err(message)) {\012    return Err(prefixPath(\"[2]\", message))\012  }\012  const fourth = Shape.fromValue<D>(items.value[3])\012  if (fourth is Err(message)) {\012    return Err(prefixPath(\"[3]\", message))\012  }\012  return Ok(#[first.value, second.value, third.value, fourth.value])\012}\012"};
